import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        @SuppressWarnings("unchecked")
        HashSet<String>[] prefixes = new HashSet[10];
        @SuppressWarnings("unchecked")
        HashSet<String>[] suffixes = new HashSet[10];

        for (int i = 1; i <= 9; i++) {
            prefixes[i] = new HashSet<>();
            suffixes[i] = new HashSet<>();
        }

        HashSet<String> substrings = new HashSet<>();

        for (int i = 0; i < n; i++) {
            String s = br.readLine().trim();
            boolean invalid = substrings.contains(s);

            for (int split = 1; split < s.length() && split < 10 && !invalid; split++) {
                int otherLength = 10 - split;
                if (otherLength <= 0 || split + otherLength != s.length()) {
                    continue;
                }
                if (suffixes[split].contains(s.substring(0, split))
                        && prefixes[otherLength].contains(s.substring(split))) {
                    invalid = true;
                }
            }

            if (invalid) {
                System.out.println(s);
                return;
            }

            for (int length = 1; length <= 9 && length <= s.length(); length++) {
                prefixes[length].add(s.substring(0, length));
                suffixes[length].add(s.substring(s.length() - length));
            }

            for (int start = 0; start + 10 <= s.length(); start++) {
                substrings.add(s.substring(start, start + 10));
            }
        }

        System.out.println("ok");
    }
}
